/* ══ GOVERNANCE ═════════════════════════════════════════════════════════
   Today one long page; here six views under one switch. Content, scales and
   wording follow the built page: aspects and their AI assessment, governing
   policy, checklist, risk register with heat map, policy library, the control
   points and KPIs from each process, and the activity record. */
const GV = [['attention', 'What needs attention'], ['assessment', 'Assessment'], ['risks', 'Risk register'], ['policies', 'Policy library'], ['controls', 'Controls & KPIs'], ['activity', 'Activity']];
const LIK = ['Low', 'Medium', 'High'], IMP = ['Low', 'Medium', 'High', 'Critical'];
function riskLevel(r) { const s = (LIK.indexOf(r.lik) + 1) * (IMP.indexOf(r.imp) + 1); return s >= 6 ? 'High' : s >= 3 ? 'Medium' : 'Low'; }
const aspectName = (id) => (S.gov.aspects.find((a) => a.id === id) || { name: '' }).name;
const policyById = (id) => S.gov.policies.find((x) => x.id === id);
function gTiles() {
  const open = S.gov.risks.filter((r) => r.status !== 'Closed'), lv = (l) => open.filter((r) => riskLevel(r) === l).length;
  const overdueActs = S.gov.risks.reduce((n, r) => n + ((r.treat && r.treat.actions) || []).filter((a) => !a.done && a.due && daysFrom(a.due) < 0).length, 0);
  const polOver = S.gov.policies.filter((x) => x.reviewDue && daysFrom(x.reviewDue) < 0).length;
  const noGov = S.gov.aspects.filter((a) => { const g = S.gov.policies.find((x) => x.governs === a.id); return !g || g.life !== 'Published'; }).length;
  const ck = S.gov.checklist, ckOver = ck.filter((c) => !c.done && c.due && daysFrom(c.due) < 0).length;
  const t = [[lv('High'), '', 'Open High risks', lv('High') ? 'bad' : '', 'risks~High'], [lv('Medium'), '', 'Open Medium risks', lv('Medium') ? 'attn' : '', 'risks~Medium'], [lv('Low'), '', 'Open Low risks', '', 'risks~Low']];
  if (overdueActs) t.push([overdueActs, '', 'Overdue treatment actions', 'bad', 'risks']);
  t.push([polOver, '', 'Policies overdue for review', polOver ? 'attn' : '', 'policies'], [noGov, ' of ' + S.gov.aspects.length, 'Aspects without a published governing policy', noGov ? 'attn' : '', 'assessment'], [ck.filter((c) => c.done).length, ' of ' + ck.length, 'Checklist items done', '', 'assessment']);
  if (ckOver) t.push([ckOver, '', 'Overdue checklist items', 'bad', 'assessment']);
  return '<div class="tiles">' + t.map(([n, of, l, tone, to]) => '<button type="button" class="tile ' + tone + '" data-go="governance~' + to + '"><b>' + n + '<small>' + of + '</small></b><span>' + l + '</span></button>').join('') + '</div>';
}
R.governance = (args) => {
  const v = GV.some((g) => g[0] === args[0]) ? args[0] : 'attention';
  return phead('Governance', { sub: 'An AI-assisted assessment of board structure, risk and controls, ethics, compensation, ESG, data integrity and accessibility; and the control points and KPIs that come from each process.' }) +
    '<div class="seg" style="margin-bottom:16px">' + GV.map(([k, l]) => '<button type="button" class="' + (k === v ? 'on' : '') + '" data-go="governance~' + k + '">' + l + '</button>').join('') + '</div>' +
    ({ attention: gAttention, assessment: gAssessment, risks: gRisks, policies: gPolicies, controls: gControls, activity: gActivity }[v])(args.slice(1));
};
function gAttention() {
  const pub = procs().filter((p) => p.status === 'PUBLISHED' && p.nextReview).sort((a, b) => a.nextReview.localeCompare(b.nextReview));
  const grp = [['Overdue', 'bad', (d) => d < 0], ['Next 30 days', 'attn', (d) => d >= 0 && d <= 30], ['31 to 90 days', '', (d) => d > 30 && d <= 90], ['Later', '', (d) => d > 90]];
  return gTiles() + '<div class="ovgrid"><div class="blk cal"><div class="blk-h"><span class="lbl">Process review calendar</span></div>' +
    (pub.length ? grp.map(([t, tone, f]) => { const r = pub.filter((p) => f(daysFrom(p.nextReview))); return r.length ? '<h4 class="' + tone + '">' + t + ' · ' + r.length + '</h4>' + r.map((p) => '<div class="calrow"><span class="num">' + dt(p.nextReview) + '</span><span><a class="pname" href="#" data-go="' + openP(p.code, 'lifecycle') + '">' + p.code + ' · ' + esc(p.name) + '</a><span class="psub">SOP v' + esc(p.doc.version) + ' · approved by ' + esc(p.doc.approvedBy) + '</span></span><span>' + (daysFrom(p.nextReview) < 0 ? '<span class="pill bad">' + plural(-daysFrom(p.nextReview), 'day') + ' late</span>' : '<span class="pill' + (tone ? ' ' + tone : '') + '">in ' + plural(daysFrom(p.nextReview), 'day') + '</span>') + '</span></div>').join('') : ''; }).join('')
      : '<p class="none">No process is published yet, so none has a review date. Publishing a process starts its review clock.</p>') + '</div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Staff reading page</span></div><p>Everything published, for staff to read and acknowledge. Send it to the people on the register.</p><div class="copyrow" style="margin-top:8px"><code>/raya/processes/read</code><button class="btn sm" type="button" data-act="copy" data-text="/raya/processes/read">Copy link</button><button class="btn sm" type="button" data-act="seeAsStaff">Open as staff</button></div></div></div>';
}
ACT.seeAsStaff = () => { UI.look = 'staff'; go('read'); };

/* assessment, by aspect */
function gAssessment() {
  const G = S.gov, a = G.aspects.find((x) => x.id === UI.f.aspect) || G.aspects[1] || G.aspects[0], as = G.assess[a.id], gp = G.policies.find((x) => x.governs === a.id);
  const tabs = '<div class="pills">' + G.aspects.map((x) => { const g = G.policies.find((y) => y.governs === x.id), od = G.checklist.filter((c) => c.aspect === x.id && !c.done && c.due && daysFrom(c.due) < 0).length; return '<button type="button" class="apill' + (x === a ? ' on' : '') + '" data-act="aspect" data-id="' + x.id + '">' + esc(x.name) + (!g || g.life !== 'Published' ? '<span class="dot" title="No published governing policy"></span>' : '') + (od ? '<span class="od">' + od + ' overdue</span>' : '') + '</button>'; }).join('') +
    '<button class="btn sm" type="button" data-act="aspectAdd">+ Add aspect</button><button class="btn sm ghost" type="button" data-act="aspectRename" aria-label="Rename this aspect">✎</button><button class="btn sm ghost" type="button" data-act="aspectDel" aria-label="Delete this aspect">✕</button></div>';
  const prof = G.profile;
  let govBlk;
  if (gp) govBlk = '<p><a class="pname" href="#" data-act="polOpen" data-id="' + gp.id + '">' + esc(gp.title) + '</a> ' + lifeChip(gp.life) + (gp.effective ? ' <span class="q">Effective ' + dt(gp.effective) + '</span>' : '') + '</p>' + (gp.life !== 'Published' ? '<p class="note" style="margin-top:4px">' + (gp.life === 'Retired' ? 'Retired: publish a replacement to govern this aspect again.' : 'Not yet published: open it to submit, approve and publish.') + '</p>' : '') + '<div class="acts" style="margin-top:8px"><button class="btn sm" type="button" data-act="govChange">Change</button><button class="btn sm ghost" type="button" data-act="govRemove" data-id="' + gp.id + '">Remove as governing policy…</button></div>';
  else govBlk = '<div class="banner attn" style="margin-bottom:8px">' + esc(a.name) + ' has no governing policy yet.</div><div class="acts"><button class="btn sm" type="button" data-act="govTemplate">Start from template</button><button class="btn sm" type="button" data-act="govAi">Draft with AI</button><button class="btn sm" type="button" data-act="govWrite">Write one</button><button class="btn sm" type="button" data-act="govChange">Choose from library</button></div>';
  const items = G.checklist.filter((c) => c.aspect === a.id);
  return '<div class="blk" style="margin-bottom:12px"><div class="blk-h"><span class="lbl">Assessed for</span><span class="r"><a class="lnk" href="#" data-go="settings">Change in Processes settings →</a></span></div><p>' + esc(prof.size) + ' · ' + esc(prof.jurisdiction) + ' · ' + esc(S.ws.industry) + '</p></div>' +
    '<div class="blk" style="margin-bottom:12px"><div class="blk-h"><span class="lbl">Evaluated against four pillars</span></div><div class="pillars"><div>Accountability</div><div>Transparency &amp; Fairness</div><div>Responsibility</div><div>Independence</div></div></div>' +
    '<div class="filters">' + tabs + '<span style="margin-left:auto" class="acts">' + (as ? '<span class="note">Last generated ' + dt(as.at) + '</span>' : '') + '<button class="btn sm gold" type="button" data-act="assessGen">' + (as ? 'Regenerate' : 'Generate assessment') + '</button></span></div>' +
    '<div class="two" style="margin-bottom:12px"><div class="blk"><div class="blk-h"><span class="lbl">Governing policy — ' + esc(a.name) + '</span></div><p class="note" style="margin-bottom:6px">The one policy that sets the rules for this aspect as a whole.</p>' + govBlk + '</div>' +
    '<div class="blk"><div class="blk-h"><span class="lbl">Executive summary — ' + esc(a.name) + '</span>' + (as ? '<button class="pen" type="button" data-act="summaryEdit">Edit</button>' : '') + '</div>' + (as ? '<p>' + esc(as.summary) + '</p>' : '<p class="none">No assessment generated yet for ' + esc(a.name) + '. Generate one above, or add a checklist item by hand.</p>') + '</div></div>' +
    '<div class="sect">Governance checklist<span class="r"><button class="btn sm" type="button" data-act="ckAdd">+ Add item</button></span></div><div class="cl3">' + ['Immediate', 'Near-term', 'Long-term'].map((w) => { const r = items.filter((c) => c.when === w); return '<div class="clc"><div class="col-h"><b>' + w + '</b><span class="n">' + r.length + '</span></div>' + (r.length ? r.map((c) => '<div class="citem' + (c.done ? ' done' : '') + '"><input type="checkbox" data-chg="ckDone" data-id="' + c.id + '"' + (c.done ? ' checked' : '') + ' aria-label="Done"><div><b>' + esc(c.title) + '</b>' + (c.desc ? '<div class="q">' + esc(c.desc) + '</div>' : '') + '<div class="q">' + (c.owner ? 'Owner: ' + esc(c.owner) : 'No owner') + (c.due ? ' · Due ' + dt(c.due) : '') + (!c.done && c.due && daysFrom(c.due) < 0 ? ' <span class="chip bad">Overdue</span>' : '') + '</div>' + (c.policy ? '<a class="lnk" href="#" data-act="polOpen" data-id="' + c.policy + '">View draft policy →</a>' : '') + '</div></div>').join('') : '<p class="note" style="padding:8px 2px">Nothing here.</p>') + '</div>'; }).join('') + '</div>';
}
const lifeChip = (l) => '<span class="chip ' + ({ Draft: '', 'In review': 'attn', Approved: 'good', Published: 'good', Retired: '' }[l]) + '">' + l + '</span>';
ACT.aspect = (el) => { UI.f.aspect = el.dataset.id; render(); };
ACT.aspectAdd = () => dialog({ title: 'Add aspect', body: fld('Aspect name', inp('as-name', '')), foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="aspectAddGo">Add</button>' });
ACT.aspectAddGo = () => { const n = val('as-name'); if (!n) return; const id = uid('a'); S.gov.aspects.push({ id, name: n }); UI.f.aspect = id; log('Aspect', n, 'Added'); UI.layer = null; render(); };
const curAspect = () => S.gov.aspects.find((x) => x.id === UI.f.aspect) || S.gov.aspects[1];
ACT.aspectRename = () => { const a = curAspect(); dialog({ title: 'Rename aspect', body: fld('Aspect name', inp('as-name', a.name)), foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="aspectRenameGo">Save</button>' }); };
ACT.aspectRenameGo = () => { const a = curAspect(), n = val('as-name'); if (n) { log('Aspect', n, 'Renamed from \'' + a.name + '\' to \'' + n + '\''); a.name = n; } UI.layer = null; render(); };
ACT.aspectDel = () => { const a = curAspect(); dialog({ title: 'Delete “' + esc(a.name) + '”?', body: '<p>Its assessment and checklist go with it. Risks and policies stay in their registers.</p>', foot: '<button class="btn" type="button" data-act="close">Keep</button><button class="btn danger solid" type="button" data-act="aspectDelGo">Delete</button>' }); };
ACT.aspectDelGo = () => { const a = curAspect(); S.gov.aspects = S.gov.aspects.filter((x) => x !== a); S.gov.checklist = S.gov.checklist.filter((c) => c.aspect !== a.id); UI.f.aspect = null; log('Aspect', a.name, 'Deleted'); UI.layer = null; render(); };
ACT.assessGen = () => {
  const a = curAspect(), was = !!S.gov.assess[a.id];
  S.gov.assess[a.id] = { at: todayIso(), summary: 'Accountability: who decides on ' + a.name.toLowerCase() + ' is not written down. Transparency & Fairness: reporting reaches management but not the board. Responsibility: one owner, no deputy. Independence: no outside review yet. (Sample text drawn for this mockup.)' };
  if (!was) S.gov.checklist.push({ id: uid('k'), aspect: a.id, title: 'Name an owner and a deputy for ' + a.name.toLowerCase(), desc: '', when: 'Immediate', owner: '', due: '', done: false, policy: null });
  log('Assessment', a.name, was ? 'Regenerated assessment' : 'Generated assessment — 1 new checklist item'); toast(was ? 'Regenerated.' : 'Assessment generated.'); render();
};
ACT.summaryEdit = () => { const a = curAspect(); dialog({ title: 'Executive summary — ' + esc(a.name), wide: true, body: area('sm-text', S.gov.assess[a.id].summary, { rows: 8 }).replace('<textarea', '<textarea class="inp"'), foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="summarySave">Save</button>' }); };
ACT.summarySave = () => { const a = curAspect(); S.gov.assess[a.id].summary = val('sm-text'); log('Assessment', a.name, 'Executive summary edited'); UI.layer = null; render(); };
CHG.ckDone = (el) => { const c = S.gov.checklist.find((x) => x.id === el.dataset.id); c.done = el.checked; if (c.done) log('Checklist item', c.title, 'Marked Done'); render(); };
ACT.ckAdd = () => dialog({ title: 'Add a checklist item', sub: esc(curAspect().name), body: '<div class="frm">' + fld('Action title', inp('ck-t', '')) + fld('Description', area('ck-d', '', { ph: 'What to do, and why it matters', rows: 2 })) + '<div class="frm two">' + fld('When', sel('ck-w', ['Immediate', 'Near-term', 'Long-term'], 'Immediate')) + fld('Owner', '<select id="ck-o"><option value="">Unassigned</option><optgroup label="Roles">' + liveRoles().map((r) => '<option>' + esc(r.name) + '</option>').join('') + '</optgroup><optgroup label="People">' + livePeople().map((p) => '<option>' + esc(p.name) + '</option>').join('') + '</optgroup></select>') + fld('Due', inp('ck-due', '', { type: 'date' })) + '</div></div>', foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="ckAddGo">Add</button>' });
ACT.ckAddGo = () => { const t = val('ck-t'); if (!t) return; S.gov.checklist.push({ id: uid('k'), aspect: curAspect().id, title: t, desc: val('ck-d'), when: val('ck-w'), owner: val('ck-o'), due: val('ck-due'), done: false, policy: null }); log('Checklist item', t, 'Added'); UI.layer = null; render(); };
const TEMPLATES = ['Board Charter', 'Risk Management Policy', 'Code of Ethics and Conduct', 'Remuneration Policy', 'Sustainability (ESG) Policy', 'Data Governance Policy', 'Accessibility Policy', 'Conflict of Interest Policy', 'Whistleblowing Policy', 'Anti-Bribery and Corruption Policy', 'Third-Party Management Policy', 'Incident Management Policy', 'Data Protection Policy', 'Training and Awareness Policy'];
ACT.govTemplate = () => { const a = curAspect(), best = { a1: 0, a2: 1, a3: 2, a4: 3, a5: 4, a6: 5, a7: 6 }[a.id]; dialog({ title: 'Start from a template', sub: 'A template is a starting point to adapt to the client, not legal advice.', body: '<div class="checks" style="max-height:320px;overflow:auto">' + TEMPLATES.map((t, i) => '<label><input type="radio" name="tpl" value="' + esc(t) + '"' + (i === best ? ' checked' : '') + '> ' + esc(t) + (i === best ? ' <span class="chip gold">Suggested</span>' : '') + '</label>').join('') + '</div>', foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="govTemplateGo">Use template</button>' }); };
ACT.govTemplateGo = () => { const t = checkedVals('tpl')[0]; if (!t) return; newGoverning(t, 'Drafted from the template.'); };
ACT.govAi = () => { newGoverning(curAspect().name + ' Policy', 'Drafted by AI from the governance profile. (Sample text for this mockup.)'); };
ACT.govWrite = () => dialog({ title: 'Write a governing policy', wide: true, body: '<div class="frm">' + fld('Policy title', inp('gw-t', curAspect().name + ' Policy')) + fld('Policy text', area('gw-b', '', { rows: 8 })) + '</div>', foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="govWriteGo">Create governing policy</button>' });
ACT.govWriteGo = () => newGoverning(val('gw-t') || curAspect().name + ' Policy', val('gw-b'));
function newGoverning(title, body) { const a = curAspect(), id = uid('pol'); S.gov.policies.push({ id, title, aspect: a.id, governs: a.id, life: 'Draft', edited: false, updated: todayIso(), effective: null, reviewDue: null, body, versions: 1, acks: [] }); log('Policy', title, 'Set as governing policy for ' + a.name); UI.layer = null; toast('Governing policy created as a draft.'); render(); }
ACT.govChange = () => { const a = curAspect(); dialog({ title: 'Choose from the library', body: fld('Policy from the library', sel('gc-p', [['', 'Choose a policy…']].concat(S.gov.policies.map((x) => [x.id, x.title + ' (' + x.life + ')'])), '')), foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="govChangeGo">Set as governing policy</button>' }); };
ACT.govChangeGo = () => { const id = val('gc-p'); if (!id) return; const a = curAspect(); S.gov.policies.forEach((x) => { if (x.governs === a.id) x.governs = null; }); policyById(id).governs = a.id; log('Policy', policyById(id).title, 'Set as governing policy for ' + a.name); UI.layer = null; render(); };
ACT.govRemove = (el) => { const x = policyById(el.dataset.id); x.governs = null; log('Policy', x.title, 'Removed as governing policy'); toast('It stays in the library.'); render(); };

/* risk register */
function gRisks(args) {
  const G = S.gov, f = UI.f.heat, lvl = args[0];
  let rows = G.risks;
  if (lvl) rows = rows.filter((r) => r.status !== 'Closed' && riskLevel(r) === lvl);
  else if (f) rows = rows.filter((r) => r.status !== 'Closed' && r.lik === f[0] && r.imp === f[1]);
  const open = G.risks.filter((r) => r.status !== 'Closed');
  const heat = '<div class="heat2"><div class="h" style="font-size:10.5px">Likelihood ↓ Impact →</div>' + IMP.map((i) => '<div class="h">' + i + '</div>').join('') + LIK.slice().reverse().map((l) => '<div class="h">' + l + '</div>' + IMP.map((i) => { const n = open.filter((r) => r.lik === l && r.imp === i).length, lv = riskLevel({ lik: l, imp: i }); return '<button type="button" class="' + { High: 'hi', Medium: 'md', Low: 'lo' }[lv] + (n ? '' : ' zero') + (f && f[0] === l && f[1] === i ? ' on' : '') + '"' + (n ? ' data-act="heat" data-l="' + l + '" data-i="' + i + '"' : ' disabled') + '>' + n + '<small>' + lv + '</small></button>'; }).join('')).join('') + '</div>';
  return '<div class="ovgrid" style="margin-bottom:14px"><div class="blk"><div class="blk-h"><span class="lbl">Risk register</span></div><p>Identified risks, tracked on their own — scored, owned, and carried forward independent of any one checklist run. Filled in by an assessment or added by hand.</p><p class="note" style="margin-top:6px">The level is worked out from likelihood and impact, never typed in.</p></div><div class="blk"><div class="blk-h"><span class="lbl">Heat map — open risks</span></div>' + heat + '</div></div>' +
    (lvl ? '<div class="banner">Showing every open ' + lvl + ' risk across all aspects (' + rows.length + '). <button class="lnk" type="button" data-go="governance~risks">Show all risks</button></div>' : f ? '<div class="banner">Showing ' + plural(rows.length, 'risk') + ' at ' + f[0] + ' likelihood, ' + f[1] + ' impact. <button class="lnk" type="button" data-act="heatClear">Show all risks</button></div>' : '') +
    '<div class="sect">' + plural(rows.length, 'risk') + '<span class="r"><button class="btn sm gold" type="button" data-act="rkAdd">+ Add risk</button></span></div><div class="tw"><table class="t"><thead><tr><th>Risk</th><th>Likelihood</th><th>Impact</th><th>Level</th><th>Owner</th><th>Status</th><th></th></tr></thead><tbody>' +
    (rows.length ? rows.map((r) => { const lv = riskLevel(r), od = r.treat && r.treat.actions.some((a) => !a.done && a.due && daysFrom(a.due) < 0), open2 = UI.open['rk-' + r.id];
      return '<tr><td style="min-width:240px"><b>' + esc(r.title) + '</b><span class="psub">' + (r.aspect ? esc(aspectName(r.aspect)) : 'Added manually') + ' · <button class="lnk" type="button" data-act="treatToggle" data-id="' + r.id + '">' + (open2 ? 'Hide treatment' : 'Treatment') + '</button>' + (od ? ' <span class="chip bad">Overdue treatment</span>' : '') + '</span></td>' +
        '<td>' + sel('rl-' + r.id, LIK, r.lik, { chg: 'rkField', data: 'data-id="' + r.id + '" data-f="lik"' }) + '</td><td>' + sel('ri-' + r.id, IMP, r.imp, { chg: 'rkField', data: 'data-id="' + r.id + '" data-f="imp"' }) + '</td><td><span class="pill ' + { High: 'bad', Medium: 'attn', Low: 'good' }[lv] + '">' + lv + '</span></td><td>' + (r.owner ? esc(r.owner) : '<span class="q">— unassigned</span>') + '</td><td>' + sel('rs-' + r.id, ['Open', 'Mitigating', 'Accepted', 'Closed'], r.status, { chg: 'rkField', data: 'data-id="' + r.id + '" data-f="status"' }) + '</td><td class="r"><button class="x" type="button" data-act="rkDel" data-id="' + r.id + '" aria-label="Delete">×</button></td></tr>' +
        (open2 ? '<tr><td colspan="7" style="background:var(--surface-2)">' + treatPanel(r) + '</td></tr>' : ''); }).join('') : '<tr><td colspan="7"><div class="empty">No risks tracked yet.</div></td></tr>') + '</tbody></table></div>';
}
function treatPanel(r) {
  const t = r.treat || { strategy: 'Not decided', tLik: '', tImp: '', rationale: '', actions: [] };
  const target = t.tLik && t.tImp ? riskLevel({ lik: t.tLik, imp: t.tImp }) : '—';
  return '<p style="margin-bottom:8px">Current level: <b>' + riskLevel(r) + '</b> → target: <b>' + target + '</b>' + (t.tLik ? ' (' + t.tLik + ' likelihood, ' + t.tImp + ' impact)' : '') + '</p><div class="frm two">' + fld('Strategy', sel('tr-s-' + r.id, ['Not decided', 'Mitigate', 'Transfer', 'Accept', 'Avoid'], t.strategy)) + '<div class="frm two" style="gap:8px">' + fld('Target likelihood', sel('tr-l-' + r.id, [['', '—']].concat(LIK), t.tLik)) + fld('Target impact', sel('tr-i-' + r.id, [['', '—']].concat(IMP), t.tImp)) + '</div>' + fld('Rationale', area('tr-r-' + r.id, t.rationale, { rows: 2 }), { full: true }) + '</div>' +
    '<div class="acts" style="margin:8px 0"><button class="btn sm" type="button" data-act="treatSave" data-id="' + r.id + '">Save treatment</button></div><div class="lbl" style="margin:6px 0">Treatment actions</div>' +
    (t.actions.length ? t.actions.map((a) => '<div class="filters" style="margin:0 0 4px"><input type="checkbox" data-chg="taDone" data-r="' + r.id + '" data-id="' + a.id + '"' + (a.done ? ' checked' : '') + ' aria-label="Done"> <span>' + esc(a.desc) + '</span><span class="q">Owner: ' + esc(a.owner || '—') + (a.due ? ' · Due ' + dt(a.due) : '') + '</span>' + (a.done ? '<span class="chip good">Done</span>' : a.due && daysFrom(a.due) < 0 ? '<span class="chip bad">Overdue</span>' : '') + '</div>').join('') : '<p class="note">No treatment actions yet.</p>') +
    '<div class="filters" style="margin-top:6px"><input class="inp" id="ta-d-' + r.id + '" placeholder="What will be done" style="max-width:300px"><input class="inp" id="ta-o-' + r.id + '" placeholder="Owner" style="max-width:160px"><input class="inp" type="date" id="ta-due-' + r.id + '" style="max-width:160px"><button class="btn sm" type="button" data-act="taAdd" data-id="' + r.id + '">Add action</button></div>';
}
ACT.heat = (el) => { UI.f.heat = UI.f.heat && UI.f.heat[0] === el.dataset.l && UI.f.heat[1] === el.dataset.i ? null : [el.dataset.l, el.dataset.i]; render(); };
ACT.heatClear = () => { UI.f.heat = null; render(); };
CHG.rkField = (el) => { const r = S.gov.risks.find((x) => x.id === el.dataset.id); r[el.dataset.f] = el.value; log('Risk', r.title, 'Edited'); render(); };
ACT.rkDel = (el) => { const r = S.gov.risks.find((x) => x.id === el.dataset.id); dialog({ title: 'Delete this risk?', body: '<p>' + esc(r.title) + '</p>', foot: '<button class="btn" type="button" data-act="close">Keep</button><button class="btn danger solid" type="button" data-act="rkDelGo" data-id="' + r.id + '">Delete</button>' }); };
ACT.rkDelGo = (el) => { const r = S.gov.risks.find((x) => x.id === el.dataset.id); S.gov.risks = S.gov.risks.filter((x) => x !== r); log('Risk', r.title, 'Deleted'); UI.layer = null; render(); };
ACT.rkAdd = () => dialog({ title: 'Add a risk', body: '<div class="frm">' + fld('Risk title', inp('rk-t', '')) + fld('Description', area('rk-d', '', { ph: 'What could go wrong, and why it matters', rows: 2 })) + '<div class="frm two">' + fld('Likelihood', sel('rk-l', LIK, 'Medium')) + fld('Impact', sel('rk-i', IMP, 'Medium')) + '</div></div>', foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="rkAddGo">Add</button>' });
ACT.rkAddGo = () => { const t = val('rk-t'); if (!t) return; S.gov.risks.unshift({ id: uid('rk'), title: t, desc: val('rk-d'), aspect: null, lik: val('rk-l'), imp: val('rk-i'), status: 'Open', owner: '', treat: null }); log('Risk', t, 'Added'); UI.layer = null; render(); };
ACT.treatToggle = (el) => { UI.open['rk-' + el.dataset.id] = !UI.open['rk-' + el.dataset.id]; render(); };
ACT.treatSave = (el) => { const r = S.gov.risks.find((x) => x.id === el.dataset.id), id = r.id; r.treat = Object.assign(r.treat || { actions: [] }, { strategy: val('tr-s-' + id), tLik: val('tr-l-' + id), tImp: val('tr-i-' + id), rationale: val('tr-r-' + id) }); log('Risk', r.title, 'Edited'); toast('Treatment saved.'); render(); };
CHG.taDone = (el) => { const r = S.gov.risks.find((x) => x.id === el.dataset.r); r.treat.actions.find((a) => a.id === el.dataset.id).done = el.checked; render(); };
ACT.taAdd = (el) => { const r = S.gov.risks.find((x) => x.id === el.dataset.id), id = r.id, d = val('ta-d-' + id); if (!d) return; r.treat = r.treat || { strategy: 'Not decided', tLik: '', tImp: '', rationale: '', actions: [] }; r.treat.actions.push({ id: uid('ta'), desc: d, owner: val('ta-o-' + id), due: val('ta-due-' + id), done: false }); render(); };

/* policy library and its drawer */
function gPolicies() {
  return '<div class="sect">Every policy, in one place <span>· drafted by an assessment, or written here by hand</span><span class="r"><button class="btn sm gold" type="button" data-act="polAdd">+ Add policy</button></span></div><div class="box">' +
    (S.gov.policies.length ? S.gov.policies.map((x) => '<div class="att" style="grid-template-columns:minmax(0,1fr) auto;cursor:pointer" data-act="polOpen" data-id="' + x.id + '"><div class="what"><b>' + esc(x.title) + '</b><span class="w2">' + (x.governs ? '<span style="color:var(--stone);font-weight:600">Governs ' + esc(aspectName(x.governs)) + '</span>' : x.aspect ? esc(aspectName(x.aspect)) : 'Added manually') + ' · updated ' + dt(x.updated) + '</span></div><span class="acts">' + (x.reviewDue && daysFrom(x.reviewDue) < 0 ? '<span class="chip bad">Needs review</span>' : '') + lifeChip(x.life) + '<span class="chip">' + (x.edited ? 'Edited' : 'Draft (untouched)') + '</span></span></div>').join('') : '<div class="empty">No policies yet. Generate an assessment that recommends one, or add one by hand.</div>') + '</div>';
}
ACT.polAdd = () => dialog({ title: 'Add a policy', wide: true, body: '<div class="frm">' + fld('Policy title', inp('pa-t', '')) + fld('Policy text', area('pa-b', '', { rows: 8, ph: 'The policy itself — sections, defined terms, whatever the client needs to review.' })) + '</div>', foot: '<button class="btn" type="button" data-act="close">Cancel</button><button class="btn gold" type="button" data-act="polAddGo">Add</button>' });
ACT.polAddGo = () => { const t = val('pa-t'); if (!t) return; S.gov.policies.push({ id: uid('pol'), title: t, aspect: null, governs: null, life: 'Draft', edited: true, updated: todayIso(), effective: null, reviewDue: null, body: val('pa-b'), versions: 1, acks: [] }); log('Policy', t, 'Added'); UI.layer = null; render(); };
ACT.polOpen = (el) => {
  const id = el.dataset.id; UI.f.polEdit = false;
  sheet({ title: esc(policyById(id).title), body: () => {
    const x = policyById(id), next = { Draft: ['Submit for review', 'In review'], 'In review': ['Approve', 'Approved'], Approved: ['Publish', 'Published'], Published: ['Retire', 'Retired'] }[x.life];
    return '<div class="filters" style="margin:0"><span class="note">' + (x.aspect ? esc(aspectName(x.aspect)) : 'Added manually') + '</span>' + lifeChip(x.life) + '<span class="chip">' + (x.edited ? 'Edited' : 'Draft (untouched)') + '</span></div>' +
      (UI.f.polEdit ? area('pol-body', x.body, { rows: 12 }).replace('<textarea', '<textarea class="inp" style="font-family:var(--mono);font-size:12.5px"') : '<pre style="white-space:pre-wrap;font:13px/1.55 var(--mono);background:var(--zebra);border:1px solid var(--line);border-radius:6px;padding:10px;margin:0">' + (esc(x.body) || '<span class="q">No text yet.</span>') + '</pre>') +
      (x.approvedBy ? '<p class="note">Approved by ' + esc(x.approvedBy) + (x.approvedAt ? ' on ' + dt(x.approvedAt) : '') + (x.effective ? ' · Effective ' + dt(x.effective) : '') + '</p>' : '') +
      (next ? '<div class="acts"><button class="btn sm gold" type="button" data-act="polLife" data-id="' + id + '" data-to="' + next[1] + '">' + next[0] + '</button><span class="note">' + (x.life === 'Draft' ? '' : 'Approve, Publish and Retire are for a workspace admin.') + '</span></div>' : '') +
      '<div class="filters" style="margin:0"><span class="note">Review due</span><input class="inp" type="date" id="pol-due" value="' + (x.reviewDue || '') + '" style="max-width:170px"><button class="btn sm" type="button" data-act="polDue" data-id="' + id + '">Set</button>' + (x.reviewDue && daysFrom(x.reviewDue) < 0 ? '<span class="chip bad">Needs review</span>' : '') + '</div>' +
      '<p class="note">Version history: ' + plural(x.versions, 'version') + '.</p>' +
      (x.life === 'Published' || x.life === 'Retired' ? '<div><div class="lbl" style="margin-bottom:6px">Acknowledged by</div>' + livePeople().filter((p) => p.reg).slice(0, 8).map((p) => '<div class="filters" style="margin:0 0 4px"><span style="min-width:150px">' + esc(p.name) + '</span>' + (x.acks.indexOf(p.id) >= 0 ? '<span class="q">— acknowledged</span><button class="btn sm ghost" type="button" data-act="polAck" data-id="' + id + '" data-p="' + p.id + '">Unmark</button>' : '<button class="btn sm ghost" type="button" data-act="polAck" data-id="' + id + '" data-p="' + p.id + '">Mark acknowledged</button>') + '</div>').join('') + '</div>' : '');
  }, foot: () => '<button class="btn danger l" type="button" data-act="polDel" data-id="' + id + '">Delete</button><button class="btn" type="button" data-act="close">Close</button>' + (UI.f.polEdit ? '<button class="btn gold" type="button" data-act="polSave" data-id="' + id + '">Save</button>' : '<button class="btn gold" type="button" data-act="polEditOn">Edit</button>') });
};
ACT.polEditOn = () => { UI.f.polEdit = true; render(); };
ACT.polSave = (el) => { const x = policyById(el.dataset.id); x.body = val('pol-body'); x.edited = true; x.versions++; x.updated = todayIso(); UI.f.polEdit = false; log('Policy', x.title, 'Edited'); render(); };
ACT.polLife = (el) => { const x = policyById(el.dataset.id), to = el.dataset.to; x.life = to; if (to === 'Approved') { x.approvedBy = 'Strategy Office'; x.approvedAt = todayIso(); } if (to === 'Published') x.effective = todayIso(); log('Policy', x.title, { 'In review': 'Submitted for review', Approved: 'Approved', Published: 'Published', Retired: 'Retired' }[to]); render(); };
ACT.polDue = (el) => { policyById(el.dataset.id).reviewDue = val('pol-due') || null; render(); };
ACT.polAck = (el) => { const x = policyById(el.dataset.id), i = x.acks.indexOf(el.dataset.p); if (i >= 0) x.acks.splice(i, 1); else { x.acks.push(el.dataset.p); log('Policy', x.title, 'Acknowledgement marked for ' + personName(el.dataset.p)); } render(); };
ACT.polDel = (el) => { const x = policyById(el.dataset.id); S.gov.policies = S.gov.policies.filter((y) => y !== x); log('Policy', x.title, 'Deleted'); UI.layer = null; toast('Policy deleted.'); render(); };

/* control points and KPIs, read from each process */
function controlPoints(p) {
  const out = [];
  workSteps(p).forEach((s) => { const ap = rulesFor(p, s.id).filter((r) => r.then === 'approval' && r.dir !== 'none'); ap.slice(1).forEach((r) => out.push({ flag: !r.who, text: r.who ? '“' + s.label + '” ' + DIR[r.dir].toLowerCase() + ' ' + money(r.value) + ' requires separate sign-off from ' + whoName(r.who) + ' in addition to the primary approver.' : '“' + s.label + '” requires a second sign-off, but nobody is assigned to it — this needs to be resolved in the Authority tab.' })); });
  return out;
}
function gControls() {
  const list = procs().filter((p) => p.steps.length || p.kpis.length);
  return '<p class="note" style="margin-bottom:10px;font-size:13px">The approval and review points built into each process, and the measures that show it performs. Control points come from each process\'s Authority tab; KPIs are edited on its Overview.</p><div class="stack">' + list.map((p) => { const cp = controlPoints(p);
    return '<div class="blk"><div class="blk-h"><span class="code">' + p.code + '</span><b>' + esc(p.name) + '</b><a class="lnk r" href="#" data-go="' + openP(p.code, 'authority') + '">Authority →</a></div><div class="two"><div><div class="lbl" style="margin-bottom:4px">Key control points</div>' + (cp.length ? '<ul style="padding-left:18px">' + cp.map((c) => '<li' + (c.flag ? ' style="color:var(--attn-tx)"' : '') + '>' + (c.flag ? '⚠ ' : '') + esc(c.text) + '</li>').join('') + '</ul>' : '<p class="none">No co-approval controls in this process\'s Authority tab yet.</p>') + '</div>' +
      '<div><div class="lbl" style="margin-bottom:4px">Operational KPIs &amp; SLAs</div>' + (p.kpis.length ? '<table class="t" style="border:1px solid var(--line);border-radius:6px"><tbody>' + p.kpis.map((k) => '<tr><td>' + esc(k.metric) + '</td><td class="num">' + esc(k.target) + '</td><td>' + esc(k.freq) + '</td></tr>').join('') + '</tbody></table>' : '<p class="none">No metrics yet.</p>') + '<button class="lnk" type="button" data-act="kpiEditFor" data-code="' + p.code + '" style="margin-top:6px">Edit</button></div></div></div>'; }).join('') + '</div>';
}
ACT.kpiEditFor = (el) => { CUR = byCode(el.dataset.code); ACT.kpiEdit(); };
function gActivity() {
  return '<p class="note" style="margin-bottom:10px;font-size:13px">Changes to aspects, assessments, checklist items, risks and policies, newest first.</p><div class="box">' + S.gov.activity.map(([when, type, name, what, by]) => '<div class="att" style="grid-template-columns:120px 110px minmax(0,1fr)"><span class="num q">' + dt(when.slice(0, 10)) + ' ' + when.slice(11) + '</span><span><span class="chip">' + type + '</span></span><span><b>' + esc(name) + '</b> — ' + esc(what) + ' <span class="q">by ' + esc(by) + '</span></span></div>').join('') + '</div><div class="acts" style="margin-top:10px"><button class="btn sm" type="button" data-act="toast" data-msg="Loads 50 more at a time in the product.">Load more</button></div>';
}
